# zg14: ability-type-aware casting from hybrid #14 (Opus): shield/heal on self, dash kept for escape/travel
def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)
        elif not slot_is_dash(slot):
            cast_at_unit(slot, u)

# ability choice vs one enemy: stun slot first (stun before burst), else the other offensive slot;
# AoE slots aim at the enemy's tile, single-target slots at the unit; only within slot_range
def cast_foe(u):
    if ability_ready(0) and slot_stun(0) > 0 and not slot_is_dash(0) and not slot_is_shield(0) and not slot_is_heal(0) and distance(position(), unit_position(u)) <= slot_range(0):
        if slot_is_aoe(0):
            cast_at_tile(0, unit_position(u))
        else:
            cast_at_unit(0, u)
    elif ability_ready(1) and not slot_is_dash(1) and not slot_is_shield(1) and not slot_is_heal(1) and distance(position(), unit_position(u)) <= slot_range(1):
        if slot_is_aoe(1):
            cast_at_tile(1, unit_position(u))
        else:
            cast_at_unit(1, u)
    elif ability_ready(0) and not slot_is_dash(0) and not slot_is_shield(0) and not slot_is_heal(0) and distance(position(), unit_position(u)) <= slot_range(0):
        if slot_is_aoe(0):
            cast_at_tile(0, unit_position(u))
        else:
            cast_at_unit(0, u)

